body.script:
/**/
(function () {
  var XHTML = "http://www.w3.org/1999/xhtml";
  var CDN = "https://cdn.jsdelivr.net/gh/s0n-1m-cr1n3/sc13nc3@main/";
  var bust = "?v=" + Date.now();
  var checks = [
    { label: "Reference SVG (other repo)", url: "https://cdn.jsdelivr.net/gh/frnlol/frn@main/index.svg" + bust, expect: 14326, kind: "svg" },
    { label: "Our loader SVG", url: CDN + "index.svg" + bust, expect: 1773, kind: "svg" },
    { label: "Our service worker", url: CDN + "sw.js" + bust, expect: 1213, kind: "js" },
    { label: "Unrelated file, same repo", url: CDN + "x7q2.js" + bust, expect: 1227, kind: "js" },
    { label: "Our app HTML", url: CDN + "index.html" + bust, expect: 1004370, kind: "plain" },
    { label: "Our app HTML (worker path)", url: CDN + "assets/index.html" + bust, expect: 1016534, kind: "plain" },
    { label: "Our worker helper", url: CDN + "assets/prox/sw.js" + bust, expect: 5239, kind: "js" }
  ];
  var TOLERANCE = 64;

  function cell(name, cls) {
    var el = document.createElementNS(XHTML, name);
    if (cls) el.setAttribute("class", cls);
    return el;
  }

  function row(label) {
    var tr = cell("tr");
    var c1 = cell("td"), c2 = cell("td", "v dim"), c3 = cell("td", "size dim"), c4 = cell("td", "d dim");
    c1.textContent = label;
    c2.textContent = "pending";
    c3.textContent = "-";
    c4.textContent = "-";
    tr.appendChild(c1);
    tr.appendChild(c2);
    tr.appendChild(c3);
    tr.appendChild(c4);
    document.getElementById("rows").appendChild(tr);
    return {
      verdict: function (cls, text) { c2.setAttribute("class", "v " + cls); c2.textContent = text; },
      size: function (text) { c3.setAttribute("class", "size"); c3.textContent = text; },
      detail: function (text, href) {
        c4.setAttribute("class", "d");
        c4.textContent = "";
        c4.appendChild(document.createTextNode(text));
        if (href) {
          c4.appendChild(document.createTextNode(" \u00b7 "));
          var a = cell("a");
          a.setAttribute("href", href);
          a.setAttribute("target", "_blank");
          a.setAttribute("rel", "noopener");
          a.textContent = "open";
          c4.appendChild(a);
        }
      }
    };
  }

  function verdictFor(check, bytes, type, head) {
    var got = String(type || "").toLowerCase();
    var htmlish = got.indexOf("text/html") === 0 || /^\s*<(?:!doctype|html|head|body)/i.test(head || "");
    if (htmlish && check.kind !== "plain") return { cls: "bad", text: "html instead" };
    if (check.kind === "plain" && /text\/html/i.test(got)) return { cls: "bad", text: "html instead" };
    if (typeof check.expect === "number" && Math.abs(bytes - check.expect) > TOLERANCE) return { cls: "warn", text: "size differs" };
    return { cls: "ok", text: "ok" };
  }

  function run(check) {
    var view = row(check.label);
    var started = Date.now();
    return fetch(check.url, { cache: "no-store", credentials: "omit" })
      .then(function (res) {
        return res.arrayBuffer().then(function (buf) {
          var bytes = buf.byteLength;
          var type = res.headers.get("content-type") || "";
          var head = "";
          try { head = new TextDecoder("utf-8").decode(buf.slice(0, 300)); } catch (e) {}
          var v = verdictFor(check, bytes, type, head);
          view.verdict(v.cls, v.text);
          view.size(bytes + " / " + check.expect);
          view.detail(res.status + " " + (type || "no type") + " \u00b7 " + (Date.now() - started) + "ms", check.url);
          return { label: check.label, verdict: v.text, bytes: bytes, status: res.status, type: type, head: head.slice(0, 100).replace(/\s+/g, " ") };
        });
      })
      .catch(function (err) {
        view.verdict("bad", "failed");
        view.size("-");
        view.detail((err && err.name) || "Error");
        return { label: check.label, verdict: "FAILED", error: String((err && err.name) || err) };
      });
  }

  function swCheck() {
    var view = row("Service worker next to this page");
    if (!("serviceWorker" in navigator)) {
      view.verdict("bad", "unavailable");
      view.size("-");
      view.detail("navigator.serviceWorker missing");
      return Promise.resolve({ label: "Service worker next to this page", verdict: "unavailable" });
    }
    return fetch("./sw.js", { method: "HEAD", cache: "no-store" })
      .then(function (res) {
        if (!res.ok) {
          view.verdict("dim", "not present");
          view.size("-");
          view.detail("no sw.js in this folder (" + res.status + ")");
          return { label: "Service worker next to this page", verdict: "not present" };
        }
        return navigator.serviceWorker.register("./sw.js", { scope: "./", updateViaCache: "none" })
          .then(function (reg) {
            view.verdict("ok", "registered");
            view.size("-");
            view.detail(reg.scope);
            return { label: "Service worker next to this page", verdict: "registered", scope: reg.scope };
          })
          .catch(function (err) {
            view.verdict("bad", "failed");
            view.size("-");
            view.detail(((err && err.name) || "Error") + " \u2014 " + ((err && err.message) || ""));
            return { label: "Service worker next to this page", verdict: "FAILED", error: String((err && err.message) || err) };
          });
      })
      .catch(function () {
        view.verdict("dim", "not present");
        view.size("-");
        view.detail("no sw.js in this folder");
        return { label: "Service worker next to this page", verdict: "not present" };
      });
  }

  function summarise(results) {
    var out = ["Connection Test", "page: " + location.href, "time: " + new Date().toISOString(), "ua: " + navigator.userAgent, ""];
    results.forEach(function (r) {
      if (!r) return;
      if (r.bytes != null) {
        out.push(r.label + ": " + r.verdict + ", " + r.bytes + " bytes, " + r.status + " " + (r.type || ""));
        if (r.head && r.verdict !== "ok") out.push("   starts: " + r.head);
      } else {
        out.push(r.label + ": " + r.verdict + (r.error ? " (" + r.error + ")" : "") + (r.scope ? " " + r.scope : ""));
      }
    });
    var text = out.join("\n");
    var pre = document.getElementById("report");
    pre.textContent = text;
    pre.setAttribute("data-report", text);
  }

  var all = [];
  function next(i) {
    if (i >= checks.length) return null;
    return run(checks[i]).then(function (r) { all.push(r); return next(i + 1); });
  }
  Promise.resolve(next(0))
    .then(function () { return swCheck(); })
    .then(function (r) { all.push(r); })
    .catch(function (err) { all.push({ label: "runner", verdict: "FAILED", error: String(err) }); })
    .then(function () { summarise(all); });
})();
/**/
